import { test } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import type { AddressInfo } from "node:net";
import { LocalLlmClient } from "../src/client.js";
function srv(h: http.RequestListener) { return new Promise<{url:string;close:()=>void}>(r => { const s = http.createServer(h); s.listen(0,"127.0.0.1",()=>r({url:`http://127.0.0.1:${(s.address() as AddressInfo).port}`,close:()=>{s.closeAllConnections?.();s.close();}})); }); }
const ok = (res: http.ServerResponse) => { res.setHeader("Content-Type","application/json"); res.end(JSON.stringify({choices:[{message:{role:"assistant",content:"d"},finish_reason:"stop"}]})); };
for (const mode of ["500","drop"]) test("gateway then models "+mode, async () => {
  let phase=0; const hs:any[]=[];
  const s = await srv((req,res)=>{ if(req.url==="/v1/models"){ if(phase===0){res.setHeader("Content-Type","application/json");return res.end(JSON.stringify({data:[{id:"m",limits_version:"1",context_length:4096}]}));} if(mode==="500"){res.statusCode=500;return res.end();} return res.destroy(); } if(req.url==="/v1/chat/completions"){hs.push(req.headers["x-task-class"]);return ok(res);} res.statusCode=404;res.end(); });
  try { const c = new LocalLlmClient({endpoint:`${s.url}/v1`,model:"m",taskClass:"subagent"} as any);
    await c.discoverAdvertisement(); phase=1; await c.discoverAdvertisement(); await c.chatCompletion([{role:"user",content:"hi"}],[]);
    console.log("PROBE",mode,JSON.stringify(hs)); } finally { s.close(); }
});
test("fallback endpoint gets gateway header", async () => {
  const hs:any[]=[]; 
  const gw = await srv((req,res)=>{ if(req.url==="/v1/models"){res.setHeader("Content-Type","application/json");return res.end(JSON.stringify({data:[{id:"m",limits_version:"1",context_length:4096}]}));} if(req.url==="/v1/chat/completions"){res.statusCode=503;return res.end("x");} res.statusCode=404;res.end(); });
  const plain = await srv((req,res)=>{ if(req.url==="/v1/chat/completions"){hs.push(req.headers["x-task-class"]);return ok(res);} res.statusCode=404;res.end(); });
  try { const c = new LocalLlmClient({endpoint:`${gw.url}/v1`,fallbackEndpoints:[`${plain.url}/v1`],model:"m",taskClass:"subagent"} as any);
    await c.discoverAdvertisement(); await c.chatCompletion([{role:"user",content:"hi"}],[]);
    console.log("PROBE fallback",JSON.stringify(hs)); } finally { gw.close(); plain.close(); }
});
EOF
